"What the Church teaches, following the order of the Creed, with the Scripture and Catechism passages behind each teaching.": "Ciò che la Chiesa insegna, secondo l’ordine del Credo, con i passi della Scrittura e del Catechismo alla base di ogni insegnamento.",
