"What the Church believes and why: the core teachings of the faith, with Scripture, the Catechism, and answers to common objections.": "Ciò che la Chiesa crede e perché: gli insegnamenti fondamentali della fede, con la Scrittura, il Catechismo e risposte alle obiezioni comuni.",
