"A novena is nine days of prayer for a particular intention. Open any saint or prayer and choose": "Una novena sono nove giorni di preghiera per un’intenzione particolare. Apri un santo o una preghiera e scegli",
"Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.": "Tieni un elenco delle persone e delle necessità per cui preghi. Quando una preghiera è esaudita, segnala e rendi grazie.",
"Tap ☆ Save on any prayer, saint, book, or article to keep it here.": "Tocca ☆ Salva su una preghiera, un santo, un libro o un articolo per tenerlo qui.",
"Entries you open will appear here.": "Le voci che apri compariranno qui.",
"Who or what would you like to pray for?": "Per chi o per che cosa vorresti pregare?",
"🔒 Your saved items, intentions, and novenas are stored only on this device, in this browser. Nothing is sent anywhere.": "🔒 Le voci salvate, le intenzioni e le novene sono conservate solo su questo dispositivo, in questo browser. Nulla viene inviato altrove.",
