"follows the Byzantine tradition, shared by the Ukrainian, Ruthenian, Melkite, Romanian, and other Greek Catholic Churches. The Maronite, Syro-Malabar, Chaldean, Armenian, Coptic, and other Eastern Catholic Churches have their own liturgies.": "segue la tradizione bizantina, condivisa dalle Chiese greco-cattoliche ucraina, rutena, melchita, romena e altre. Le Chiese cattoliche orientali maronita, siro-malabarese, caldea, armena, copta e altre hanno le proprie liturgie.",
