"The encyclopedia Sanctify members write together: parishes and shrines, devotions, local customs, how-tos, and anything else worth knowing. Anyone with a free account can start or improve a page, and every change is kept.": "L’enciclopedia che i membri di Sanctify scrivono insieme: parrocchie e santuari, devozioni, usanze locali, guide pratiche e tutto ciò che vale la pena sapere. Chiunque abbia un account gratuito può avviare o migliorare una pagina, e ogni modifica viene conservata.",
